 * Core vulnerability interface with comprehensive metadata
 */
export interface Vulnerability {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly severity: VulnerabilitySeverity;
  readonly category: VulnerabilityCategory;
  readonly confidence: number; // 0-100
  readonly riskScore: number; // Calculated risk score 0-10

  // Location and context
  readonly location: {
    readonly file?: string;
    readonly line?: number;
    readonly column?: number;
    readonly function?: string;
    readonly endpoint?: string;
    readonly parameter?: string;
    readonly component?: string;
  };

  // Standards compliance
  readonly cwe?: string; // Common Weakness Enumeration
  readonly cve?: string; // Common Vulnerabilities and Exposures
  readonly owaspCategory?: string; // OWASP Top 10 category
  readonly cvssVector?: string; // CVSS vulnerability vector
  readonly cvssScore?: number; // CVSS base score

  // Impact assessment
  readonly impact: {
    readonly confidentiality: "none" | "low" | "high";
    readonly integrity: "none" | "low" | "high";
    readonly availability: "none" | "low" | "high";
    readonly scope: "unchanged" | "changed";
    readonly exploitability: "none" | "low" | "high";
  };

  // Remediation guidance
  readonly remediation: {
    readonly effort: "low" | "medium" | "high";
    readonly priority: number; // 1-5 priority ranking
    readonly timeToFix: string; // Estimated time to fix
    readonly suggestions: readonly string[];
    readonly references: readonly string[];
    readonly automatedFix?: boolean;
    readonly fixComplexity: "simple" | "moderate" | "complex";
  };

  // Metadata
  readonly discoveredAt: Date;
  readonly lastUpdated: Date;
  readonly status: VulnerabilityStatus;
  readonly tags: readonly string[];
  readonly evidenceFiles?: readonly string[];
  readonly reproducer?: string; // Steps to reproduce
}

/**
 * Comprehensive scan configuration
 */
export interface VulnerabilityAssessmentConfig {
  readonly scanId?: string;
  readonly scanType: ScanType;
  readonly targets: readonly {
    readonly type: TargetType;
    readonly path: string;
    readonly priority: number;
  }[];

  // Scan parameters
  readonly maxDuration?: number; // Maximum scan duration in ms
  readonly maxVulnerabilities?: number; // Limit on vulnerabilities to report
  readonly severityThreshold?: VulnerabilitySeverity;
  readonly includePatterns?: readonly string[];
  readonly excludePatterns?: readonly string[];
  readonly followRedirects?: boolean;
  readonly authenticateAs?: string; // User role to authenticate as during scan

  // OWASP Top 10 specific settings
  readonly owaspCategories?: readonly string[];
  readonly deepInspection?: boolean;
  readonly staticAnalysis?: boolean;
  readonly dynamicAnalysis?: boolean;
  readonly configurationAnalysis?: boolean;
  readonly dependencyAnalysis?: boolean;
  readonly containerAnalysis?: boolean;

  // Reporting and output
  readonly outputFormat?: readonly (
    | "json"
    | "xml"
    | "html"
    | "sarif"
    | "csv"
  )[];
  readonly reportPath?: string;
  readonly includeEvidence?: boolean;
  readonly generateRemediation?: boolean;
  readonly complianceFrameworks?: readonly string[]; // e.g., 'NIST', 'ISO27001', 'SOC2'
}

/**
 * Comprehensive assessment result
 */
export interface VulnerabilityAssessmentResult {
  readonly scanId: string;
  readonly scanType: ScanType;
  readonly startedAt: Date;
  readonly completedAt: Date;
  readonly duration: number; // Duration in milliseconds
  readonly status: "completed" | "failed" | "timeout" | "cancelled" | "partial";
  readonly error?: string;

  // Results summary
  readonly vulnerabilities: readonly Vulnerability[];
  readonly summary: {
    readonly total: number;
    readonly critical: number;
    readonly high: number;
    readonly medium: number;
    readonly low: number;
    readonly info: number;
    readonly byCategory: Readonly<Record<VulnerabilityCategory, number>>;
    readonly byOwaspCategory: Readonly<Record<string, number>>;
  };

  // Scan coverage and metrics
  readonly coverage: {
    readonly targetsScanned: number;
    readonly filesScanned: number;
    readonly linesOfCode?: number;
    readonly endpointsScanned?: number;
    readonly configsAnalyzed?: number;
    readonly dependenciesChecked?: number;
    readonly containerLayersScanned?: number;
    readonly coveragePercentage: number; // 0-100
  };

  // Risk assessment
  readonly riskAssessment: {
    readonly overallRiskScore: number; // 0-10
    readonly riskLevel: "very_low" | "low" | "medium" | "high" | "very_high";
    readonly criticalPath: readonly string[]; // Critical vulnerabilities that need immediate attention
    readonly businessImpact: "minimal" | "low" | "moderate" | "high" | "severe";
    readonly remediationPriority: readonly {
      readonly vulnerabilityId: string;
      readonly priority: number;
      readonly justification: string;
    }[];
  };

  // Compliance and recommendations
  readonly compliance: Readonly<
    Record<
      string,
      {
        readonly status: "compliant" | "non_compliant" | "partial";
        readonly violations: readonly string[];
        readonly score: number;
      }
    >
  >;

  readonly recommendations: readonly {
    readonly category: string;
    readonly priority: number;
    readonly title: string;
    readonly description: string;
    readonly actionable: boolean;
    readonly estimatedEffort: string;
  }[];

  readonly nextScanRecommendation: Date;
  readonly scannerVersion: string;
  readonly rulesVersion: string;
}

