  /**
   * Scan configuration files for vulnerabilities
   */
  private async scanConfigurationFiles(
    target: string,
    config: VulnerabilityAssessmentConfig,
  ): Promise<Vulnerability[]> {
    const vulnerabilities: Vulnerability[] = [];

    try {
      // Read configuration file
      const fileContent = await fs.readFile(target, "utf-8");
      const lines = fileContent.split("\n");

      // Scan for OWASP Top 10 patterns
      for (const [patternKey, patternConfig] of Object.entries(
        OWASP_VULNERABILITY_PATTERNS,
      )) {
        if (
          config.owaspCategories &&
          !config.owaspCategories.includes(patternConfig.owaspId)
        ) {
          continue;
        }

        for (const pattern of patternConfig.patterns) {
          let match;
          let lineNumber = 0;

          for (const line of lines) {
            lineNumber++;
            pattern.lastIndex = 0; // Reset regex state

            if ((match = pattern.exec(line)) !== null) {
              vulnerabilities.push(
                this.createVulnerability({
                  title: `${patternKey.replace(/_/g, " ")} - Configuration Issue`,
                  description: `Potential ${patternKey.toLowerCase().replace(/_/g, " ")} detected in configuration file. Pattern: ${match[0]}`,
                  severity: patternConfig.severity,
                  category: patternConfig.category,
                  owaspCategory: patternConfig.owaspId,
                  location: {
                    file: target,
                    line: lineNumber,
                    column: match.index,
                  },
                  impact: {
                    confidentiality:
                      patternConfig.severity === "critical" ||
                      patternConfig.severity === "high"
                        ? "high"
                        : "low",
                    integrity:
                      patternConfig.severity === "critical" ? "high" : "low",
                    availability:
                      patternConfig.severity === "critical" ? "low" : "none",
                    scope: "unchanged",
                    exploitability:
                      patternConfig.severity === "critical" ||
                      patternConfig.severity === "high"
                        ? "high"
                        : "low",
                  },
                  remediation: {
                    effort: "medium",
                    priority:
                      patternConfig.severity === "critical"
                        ? 1
                        : patternConfig.severity === "high"
                          ? 2
                          : 3,
                    timeToFix:
                      patternConfig.severity === "critical"
                        ? "2-4 hours"
                        : "30-60 minutes",
                    suggestions:
                      this.generateRemediationSuggestions(patternKey),
                    references: [
                      `https://owasp.org/Top10/${patternConfig.owaspId.split(":")[0]}_${patternConfig.owaspId.split(":")[1]}-${patternKey.split("_").slice(0, -1).join("_")}/`,
                    ],
                    automatedFix: false,
                    fixComplexity: "moderate",
                  },
                }),
              );
            }
          }
        }
      }
    } catch (error) {
      this.logger.error(`Failed to scan configuration file ${target}:`, error);
    }

    return vulnerabilities;
  }

