  /**
   * Create vulnerability instance with comprehensive metadata
   */
  private createVulnerability(config: {
    title: string;
    description: string;
    severity: VulnerabilitySeverity;
    category: VulnerabilityCategory;
    owaspCategory?: string;
    location: Partial<Vulnerability["location"]>;
    cwe?: string;
    cve?: string;
    cvssVector?: string;
    cvssScore?: number;
    impact: Vulnerability["impact"];
    remediation: Vulnerability["remediation"];
  }): Vulnerability {
    const now = new Date();
    const riskScore = this.calculateRiskScore(config.severity, config.impact);

    return {
      id: this.generateVulnerabilityId(),
      title: config.title,
      description: config.description,
      severity: config.severity,
      category: config.category,
      confidence: this.calculateConfidence(
        config.category,
        config.cve ? true : false,
      ),
      riskScore,
      location: config.location,
      cwe: config.cwe || this.generateCWE(config.category),
      cve: config.cve,
      owaspCategory: config.owaspCategory,
      cvssVector: config.cvssVector,
      cvssScore: config.cvssScore,
      impact: config.impact,
      remediation: config.remediation,
      discoveredAt: now,
      lastUpdated: now,
      status: "new",
      tags: this.generateTags(config.category, config.severity),
    };
  }

  /**
   * Calculate risk score based on severity and impact
   */
  private calculateRiskScore(
    severity: VulnerabilitySeverity,
    impact: Vulnerability["impact"],
  ): number {
    const severityScores = {
      info: 1,
      low: 3,
      medium: 5,
      high: 7,
      critical: 10,
    };

    const impactScores = {
      none: 0,
      low: 2,
      high: 5,
    };

    const baseScore = severityScores[severity];
    const impactMultiplier =
      (impactScores[impact.confidentiality] +
        impactScores[impact.integrity] +
        impactScores[impact.availability]) /
      15; // Normalize to 0-1

    const exploitabilityMultiplier =
      impact.exploitability === "high"
        ? 1.2
        : impact.exploitability === "low"
          ? 0.8
          : 1.0;
    const scopeMultiplier = impact.scope === "changed" ? 1.1 : 1.0;

    return Math.min(
      10,
      Math.round(
        baseScore *
          (1 + impactMultiplier) *
          exploitabilityMultiplier *
          scopeMultiplier *
          100,
      ) / 100,
    );
  }

  /**
   * Calculate confidence score based on detection method
   */
  private calculateConfidence(
    category: VulnerabilityCategory,
    hasCVE: boolean,
  ): number {
    const baseConfidence = {
      owasp_top_10: 85,
      configuration: 90,
      dependency: hasCVE ? 95 : 80,
      code_quality: 75,
      network: 80,
      container: 85,
    };

    return baseConfidence[category] + (hasCVE ? 10 : 0);
  }

  /**
   * Generate CWE identifier based on category
   */
  private generateCWE(category: VulnerabilityCategory): string {
    const cweMappings = {
      owasp_top_10: ["CWE-79", "CWE-89", "CWE-22", "CWE-352", "CWE-306"],
      configuration: ["CWE-16", "CWE-209", "CWE-200"],
      dependency: ["CWE-1104", "CWE-937"],
      code_quality: ["CWE-710", "CWE-398"],
      network: ["CWE-319", "CWE-300"],
      container: ["CWE-250", "CWE-269"],
    };

    const options = cweMappings[category] || ["CWE-noinfo"];
    return options[Math.floor(Math.random() * options.length)];
  }

  /**
   * Generate relevant tags for vulnerability
   */
  private generateTags(
    category: VulnerabilityCategory,
    severity: VulnerabilitySeverity,
  ): readonly string[] {
    const baseTags = [category, severity];

    const additionalTags = {
      owasp_top_10: ["web-security", "application-security"],
      configuration: ["misconfiguration", "hardening"],
      dependency: ["third-party", "supply-chain"],
      code_quality: ["static-analysis", "code-review"],
      network: ["network-security", "infrastructure"],
      container: ["containerization", "docker"],
    };

    return [...baseTags, ...(additionalTags[category] || [])];
  }

  /**
   * Filter vulnerabilities by severity threshold
   */
  private filterBySeverityThreshold(
    vulnerabilities: Vulnerability[],
    threshold: VulnerabilitySeverity,
  ): Vulnerability[] {
    const severityOrder: VulnerabilitySeverity[] = [
      "info",
      "low",
      "medium",
      "high",
      "critical",
    ];
    const thresholdIndex = severityOrder.indexOf(threshold);

    return vulnerabilities.filter((vuln) => {
      const vulnIndex = severityOrder.indexOf(vuln.severity);
      return vulnIndex >= thresholdIndex;
    });
  }

  /**
   * Calculate vulnerability summary statistics
   */
  private calculateVulnerabilitySummary(vulnerabilities: Vulnerability[]) {
    const summary = {
      total: vulnerabilities.length,
      critical: 0,
      high: 0,
      medium: 0,
      low: 0,
      info: 0,
      byCategory: {
        owasp_top_10: 0,
        configuration: 0,
        dependency: 0,
        code_quality: 0,
        network: 0,
        container: 0,
      } as Record<VulnerabilityCategory, number>,
      byOwaspCategory: {} as Record<string, number>,
    };

    vulnerabilities.forEach((vuln) => {
      // Count by severity
      summary[vuln.severity]++;

      // Count by category
      summary.byCategory[vuln.category]++;

      // Count by OWASP category if present
      if (vuln.owaspCategory) {
        summary.byOwaspCategory[vuln.owaspCategory] =
          (summary.byOwaspCategory[vuln.owaspCategory] || 0) + 1;
      }
    });

    return summary;
  }

  /**
   * Calculate scan coverage percentage
   */
  private calculateCoveragePercentage(
    targets: readonly { type: TargetType; path: string; priority: number }[],
    targetsScanned: number,
  ): number {
    if (targets.length === 0) return 100;
    return Math.round((targetsScanned / targets.length) * 100);
  }

  /**
   * Perform comprehensive risk assessment
   */
  private performRiskAssessment(vulnerabilities: Vulnerability[]) {
    const totalRiskScore = vulnerabilities.reduce(
      (sum, vuln) => sum + vuln.riskScore,
      0,
    );
    const averageRiskScore =
      vulnerabilities.length > 0 ? totalRiskScore / vulnerabilities.length : 0;
    const overallRiskScore = Math.min(10, Math.max(0, averageRiskScore));

    // Determine risk level
    let riskLevel: "very_low" | "low" | "medium" | "high" | "very_high";
    if (overallRiskScore >= 8) riskLevel = "very_high";
    else if (overallRiskScore >= 6) riskLevel = "high";
    else if (overallRiskScore >= 4) riskLevel = "medium";
    else if (overallRiskScore >= 2) riskLevel = "low";
    else riskLevel = "very_low";

    // Identify critical path vulnerabilities
    const criticalPath = vulnerabilities
      .filter((vuln) => vuln.severity === "critical" || vuln.riskScore >= 8)
      .sort((a, b) => b.riskScore - a.riskScore)
      .slice(0, 5)
      .map((vuln) => vuln.id);

    // Determine business impact
    const criticalCount = vulnerabilities.filter(
      (v) => v.severity === "critical",
    ).length;
    const highCount = vulnerabilities.filter(
      (v) => v.severity === "high",
    ).length;

    let businessImpact: "minimal" | "low" | "moderate" | "high" | "severe";
    if (criticalCount >= 5) businessImpact = "severe";
    else if (criticalCount >= 2 || highCount >= 10) businessImpact = "high";
    else if (criticalCount >= 1 || highCount >= 5) businessImpact = "moderate";
    else if (highCount >= 1) businessImpact = "low";
    else businessImpact = "minimal";

    // Create remediation priority list
    const remediationPriority = vulnerabilities
      .sort((a, b) => {
        // Sort by remediation priority first, then by risk score
        if (a.remediation.priority !== b.remediation.priority) {
          return a.remediation.priority - b.remediation.priority;
        }
        return b.riskScore - a.riskScore;
      })
      .slice(0, 10)
      .map((vuln) => ({
        vulnerabilityId: vuln.id,
        priority: vuln.remediation.priority,
        justification: `${vuln.severity.toUpperCase()} severity ${vuln.category} vulnerability with risk score ${vuln.riskScore}`,
      }));

    return {
      overallRiskScore,
      riskLevel,
      criticalPath,
      businessImpact,
      remediationPriority,
    };
  }

  /**
   * Generate compliance report for specified frameworks
   */
  private generateComplianceReport(
    vulnerabilities: Vulnerability[],
    frameworks?: readonly string[],
  ): Record<
    string,
    {
      status: "compliant" | "non_compliant" | "partial";
      violations: readonly string[];
      score: number;
    }
  > {
    const compliance: Record<
      string,
      {
        status: "compliant" | "non_compliant" | "partial";
        violations: readonly string[];
        score: number;
      }
    > = {};

    const defaultFrameworks = frameworks || ["OWASP", "NIST", "ISO27001"];

    defaultFrameworks.forEach((framework) => {
      const violations: string[] = [];
      let score = 100;

      // Mock compliance checking
      vulnerabilities.forEach((vuln) => {
        if (vuln.severity === "critical") {
          violations.push(`Critical vulnerability: ${vuln.title}`);
          score -= 20;
        } else if (vuln.severity === "high") {
          violations.push(`High severity vulnerability: ${vuln.title}`);
          score -= 10;
        }
      });

      score = Math.max(0, score);

      let status: "compliant" | "non_compliant" | "partial";
      if (score >= 90) status = "compliant";
      else if (score >= 70) status = "partial";
      else status = "non_compliant";

      compliance[framework] = {
        status,
        violations,
        score,
      };
    });

    return compliance;
  }

  /**
   * Generate actionable recommendations
   */
  private generateRecommendations(
    vulnerabilities: Vulnerability[],
    riskAssessment: ReturnType<
      VulnerabilityAssessmentEngine["performRiskAssessment"]
    >,
  ) {
    const recommendations = [];

    // High priority recommendations based on critical vulnerabilities
    const criticalVulns = vulnerabilities.filter(
      (v) => v.severity === "critical",
    );
    if (criticalVulns.length > 0) {
      recommendations.push({
        category: "Critical Vulnerabilities",
        priority: 1,
        title: "Address Critical Security Vulnerabilities Immediately",
        description: `${criticalVulns.length} critical vulnerabilities detected that require immediate attention. These pose severe security risks to your application.`,
        actionable: true,
        estimatedEffort: `${criticalVulns.length * 4} hours`,
      });
    }

    // OWASP Top 10 specific recommendations
    const owaspVulns = vulnerabilities.filter(
      (v) => v.category === "owasp_top_10",
    );
    if (owaspVulns.length > 0) {
      recommendations.push({
        category: "OWASP Top 10 Compliance",
        priority: 2,
        title: "Implement OWASP Top 10 Security Controls",
        description: `${owaspVulns.length} OWASP Top 10 vulnerabilities detected. Implement comprehensive security controls to address these common security risks.`,
        actionable: true,
        estimatedEffort: `${owaspVulns.length * 2} hours`,
      });
    }

    // Configuration improvements
    const configVulns = vulnerabilities.filter(
      (v) => v.category === "configuration",
    );
    if (configVulns.length > 0) {
      recommendations.push({
        category: "Security Configuration",
        priority: 3,
        title: "Harden Security Configuration",
        description: `${configVulns.length} configuration issues detected. Review and harden your security configuration settings.`,
        actionable: true,
        estimatedEffort: `${configVulns.length} hours`,
      });
    }

    // General security improvements
    if (riskAssessment.overallRiskScore >= 6) {
      recommendations.push({
        category: "Overall Security Posture",
        priority: 4,
        title: "Implement Continuous Security Monitoring",
        description:
          "High risk score detected. Implement continuous security monitoring and regular vulnerability assessments.",
        actionable: true,
        estimatedEffort: "8-16 hours",
      });
    }

    return recommendations;
  }

  /**
   * Calculate next scan recommendation date
   */
  private calculateNextScanDate(overallRiskScore: number): Date {
    const now = new Date();
    let daysUntilNextScan: number;

    if (overallRiskScore >= 8)
      daysUntilNextScan = 1; // Daily for very high risk
    else if (overallRiskScore >= 6)
      daysUntilNextScan = 3; // Every 3 days for high risk
    else if (overallRiskScore >= 4)
      daysUntilNextScan = 7; // Weekly for medium risk
    else if (overallRiskScore >= 2)
      daysUntilNextScan = 14; // Bi-weekly for low risk
    else daysUntilNextScan = 30; // Monthly for very low risk

    return new Date(now.getTime() + daysUntilNextScan * 24 * 60 * 60 * 1000);
  }

  /**
   * Generate unique scan ID
   */
  private generateScanId(): string {
    return `vuln_scan_${Date.now()}_${randomBytes(8).toString("hex")}`;
  }

  /**
   * Generate unique vulnerability ID
   */
  private generateVulnerabilityId(): string {
    return `vuln_${Date.now()}_${randomBytes(8).toString("hex")}`;
  }

  /**
   * Get scan history
   */
  public getScanHistory(limit?: number): VulnerabilityAssessmentResult[] {
    const scans = Array.from(this.scanHistory.values()).sort(
      (a, b) => b.startedAt.getTime() - a.startedAt.getTime(),
    );

    return limit ? scans.slice(0, limit) : scans;
  }

  /**
   * Get scan by ID
   */
  public getScanById(scanId: string): VulnerabilityAssessmentResult | null {
    return this.scanHistory.get(scanId) || null;
  }

  /**
   * Get active scans
   */
  public getActiveScans(): string[] {
    return Array.from(this.activeScans.keys());
  }

  /**
   * Cancel active scan
   */
  public async cancelScan(scanId: string): Promise<boolean> {
    const activeScan = this.activeScans.get(scanId);
    if (activeScan) {
      // In a real implementation, this would signal the scan to stop
      this.activeScans.delete(scanId);
      this.emit("scan_cancelled", { scanId });
      return true;
    }
    return false;
  }

  /**
   * Get engine statistics
   */
  public getEngineStats(): {
    totalScans: number;
    activeScans: number;
    totalVulnerabilities: number;
    averageRiskScore: number;
    patternsCached: number;
  } {
    const allScans = this.getScanHistory();
    const totalVulnerabilities = allScans.reduce(
      (sum, scan) => sum + scan.summary.total,
      0,
    );
    const averageRiskScore =
      allScans.length > 0
        ? allScans.reduce(
            (sum, scan) => sum + scan.riskAssessment.overallRiskScore,
            0,
          ) / allScans.length
        : 0;

    return {
      totalScans: allScans.length,
      activeScans: this.activeScans.size,
      totalVulnerabilities,
      averageRiskScore: Math.round(averageRiskScore * 100) / 100,
      patternsCached: this.patternCache.size,
    };
  }
}

// Export singleton instance
export const vulnerabilityAssessmentEngine =
  new VulnerabilityAssessmentEngine();

// Default export
export default VulnerabilityAssessmentEngine;

