/**
 * Comprehensive Vulnerability Reporting Engine for Bytebot Security Framework
 *
 * Enterprise-grade vulnerability reporting system providing detailed reports,
 * trend analysis, and export capabilities for local Bytebot deployments.
 * Generates actionable remediation guidance and compliance reports.
 *
 * @fileoverview Vulnerability Reporting Engine - Production Ready
 * @version 2.0.0
 * @author Reporting Specialist - Advanced Security Framework
 */

import * as fs from "fs/promises";
import * as path from "path";
import { performance } from "perf_hooks";
import { EventEmitter } from "events";
import { randomBytes, createHash } from "crypto";

// Import types from vulnerability assessment engine
import type {
  Vulnerability,
  VulnerabilityAssessmentResult,
  VulnerabilitySeverity,
  VulnerabilityCategory,
  ScanType,
} from "./vulnerability-assessment-engine";

import type {
  ConfigurationIssue,
  ConfigurationAnalysisResult,
  MisconfigurationSeverity,
  ConfigurationType,
  SecurityLevel,
} from "./configuration-analyzer";

// ===========================
// REPORTING TYPES AND INTERFACES
// ===========================

export type ReportFormat =
  | "json"
  | "xml"
  | "html"
  | "pdf"
  | "csv"
  | "sarif"
  | "markdown"
  | "xlsx";
export type ReportType =
  | "vulnerability"
  | "configuration"
  | "compliance"
  | "executive"
  | "technical"
  | "trend";
export type ExportScope =
  | "full"
  | "summary"
  | "critical_only"
  | "high_priority"
  | "remediation_plan";
export type TrendPeriod =
  | "daily"
  | "weekly"
  | "monthly"
  | "quarterly"
  | "yearly";

/**
 * Comprehensive report configuration
 */
export interface ReportConfiguration {
  readonly reportId?: string;
  readonly reportType: ReportType;
  readonly format: ReportFormat;
  readonly scope: ExportScope;
  readonly title?: string;
  readonly description?: string;

  // Data sources
  readonly vulnerabilityAssessments?: readonly string[]; // Assessment IDs
  readonly configurationAnalyses?: readonly string[]; // Analysis IDs
  readonly customData?: Record<string, any>;

  // Report parameters
  readonly severityThreshold?: VulnerabilitySeverity | MisconfigurationSeverity;
  readonly includeEvidence?: boolean;
  readonly includeRemediation?: boolean;
  readonly includeCompliance?: boolean;
  readonly includeTrendAnalysis?: boolean;
  readonly includeExecutiveSummary?: boolean;
  readonly includeTechnicalDetails?: boolean;

  // Filtering and sorting
  readonly categoryFilter?: readonly (
    | VulnerabilityCategory
    | ConfigurationType
  )[];
  readonly tagFilter?: readonly string[];
  readonly dateRange?: {
    readonly from: Date;
    readonly to: Date;
  };

  // Output configuration
  readonly outputPath?: string;
  readonly templatePath?: string;
  readonly includeCharts?: boolean;
  readonly includeMetrics?: boolean;
  readonly embedAssets?: boolean;

  // Branding and customization
  readonly companyName?: string;
  readonly companyLogo?: string;
  readonly contactInfo?: string;
  readonly customCSS?: string;
  readonly customFooter?: string;
}

/**
 * Generated report metadata
 */
export interface GeneratedReport {
  readonly reportId: string;
  readonly reportType: ReportType;
  readonly format: ReportFormat;
  readonly title: string;
  readonly description?: string;

  // Generation details
  readonly generatedAt: Date;
  readonly generatedBy: string;
  readonly generationDuration: number;
  readonly dataSourceCount: number;

  // Report content summary
  readonly summary: {
    readonly totalVulnerabilities: number;
    readonly totalConfigIssues: number;
    readonly criticalFindings: number;
    readonly highPriorityFindings: number;
    readonly overallRiskScore: number;
    readonly complianceScore: number;
  };

  // File information
  readonly filePath?: string;
  readonly fileSize?: number;
  readonly checksum?: string;

  // Report sections
  readonly sections: readonly {
    readonly name: string;
    readonly type: string;
    readonly itemCount: number;
    readonly riskLevel: "low" | "medium" | "high" | "critical";
  }[];

  // Trends and analytics
  readonly trends?: {
    readonly period: TrendPeriod;
    readonly dataPoints: readonly {
      readonly date: Date;
      readonly vulnerabilities: number;
      readonly riskScore: number;
      readonly complianceScore: number;
    }[];
    readonly insights: readonly string[];
  };

  // Export metadata
  readonly exportedAt: Date;
  readonly version: string;
}

/**
 * Report template configuration
 */
export interface ReportTemplate {
  readonly templateId: string;
  readonly name: string;
  readonly description: string;
  readonly reportType: ReportType;
  readonly supportedFormats: readonly ReportFormat[];

  // Template structure
  readonly sections: readonly {
    readonly id: string;
    readonly name: string;
    readonly required: boolean;
    readonly dataSource: string;
    readonly template: string;
  }[];

  // Styling and layout
  readonly styles: {
    readonly css: string;
    readonly layout: "single-column" | "two-column" | "dashboard";
    readonly theme: "light" | "dark" | "corporate";
  };

  readonly createdAt: Date;
  readonly updatedAt: Date;
}

/**
 * Trend analysis data
 */
export interface TrendAnalysis {
  readonly analysisId: string;
  readonly period: TrendPeriod;
  readonly startDate: Date;
  readonly endDate: Date;

  // Vulnerability trends
  readonly vulnerabilityTrends: {
    readonly totalVulnerabilities: readonly { date: Date; count: number }[];
    readonly bySeverity: Readonly<
      Record<VulnerabilitySeverity, readonly { date: Date; count: number }[]>
    >;
    readonly byCategory: Readonly<
      Record<VulnerabilityCategory, readonly { date: Date; count: number }[]>
    >;
    readonly newVulnerabilities: readonly { date: Date; count: number }[];
    readonly fixedVulnerabilities: readonly { date: Date; count: number }[];
  };

  // Risk score trends
  readonly riskTrends: {
    readonly overallRiskScore: readonly { date: Date; score: number }[];
    readonly byComponent: Readonly<
      Record<string, readonly { date: Date; score: number }[]>
    >;
    readonly riskReduction: readonly { date: Date; reduction: number }[];
  };

  // Compliance trends
  readonly complianceTrends: {
    readonly overallScore: readonly { date: Date; score: number }[];
    readonly byFramework: Readonly<
      Record<string, readonly { date: Date; score: number }[]>
    >;
    readonly violations: readonly { date: Date; count: number }[];
  };

  // Insights and recommendations
  readonly insights: readonly {
    readonly type: "improvement" | "degradation" | "stable" | "critical";
    readonly title: string;
    readonly description: string;
    readonly recommendation: string;
    readonly priority: number;
  }[];

  readonly generatedAt: Date;
}

// ===========================
// COMPREHENSIVE REPORTING ENGINE
// ===========================

/**
 * Vulnerability Reporting Engine
 *
 * Enterprise-grade reporting system with support for multiple formats,
 * trend analysis, compliance reporting, and executive dashboards.
 */
export class VulnerabilityReportingEngine extends EventEmitter {
  private readonly reportHistory: Map<string, GeneratedReport> = new Map();
  private readonly reportTemplates: Map<string, ReportTemplate> = new Map();
  private readonly activeReports: Map<string, Promise<GeneratedReport>> =
    new Map();
  private readonly trendDataCache: Map<string, TrendAnalysis> = new Map();
  private readonly logger: Console;

  constructor() {
    super();
    this.logger = console;
    this.initializeDefaultTemplates();
  }

  /**
   * Initialize default report templates
   */
  private initializeDefaultTemplates(): void {
    const startTime = performance.now();

    try {
      // Executive Summary Template
      this.reportTemplates.set("executive-summary", {
        templateId: "executive-summary",
        name: "Executive Summary Report",
        description:
          "High-level security overview for executives and management",
        reportType: "executive",
        supportedFormats: ["html", "pdf", "markdown"],
        sections: [
          {
            id: "exec-overview",
            name: "Security Overview",
            required: true,
            dataSource: "summary",
            template: "exec-overview-template",
          },
          {
            id: "risk-assessment",
            name: "Risk Assessment",
            required: true,
            dataSource: "risk-data",
            template: "risk-assessment-template",
          },
          {
            id: "compliance-status",
            name: "Compliance Status",
            required: true,
            dataSource: "compliance-data",
            template: "compliance-template",
          },
          {
            id: "recommendations",
            name: "Key Recommendations",
            required: true,
            dataSource: "recommendations",
            template: "recommendations-template",
          },
        ],
        styles: {
          css: "executive-styles",
          layout: "single-column",
          theme: "corporate",
        },
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      // Technical Report Template
      this.reportTemplates.set("technical-detailed", {
        templateId: "technical-detailed",
        name: "Technical Detailed Report",
        description: "Comprehensive technical report for security teams",
        reportType: "technical",
        supportedFormats: ["html", "json", "sarif", "csv"],
        sections: [
          {
            id: "vulnerability-details",
            name: "Vulnerability Details",
            required: true,
            dataSource: "vulnerabilities",
            template: "vulnerability-details-template",
          },
          {
            id: "configuration-issues",
            name: "Configuration Issues",
            required: true,
            dataSource: "configuration",
            template: "configuration-template",
          },
          {
            id: "remediation-plan",
            name: "Remediation Plan",
            required: true,
            dataSource: "remediation",
            template: "remediation-template",
          },
          {
            id: "technical-metrics",
            name: "Technical Metrics",
            required: false,
            dataSource: "metrics",
            template: "metrics-template",
          },
        ],
        styles: {
          css: "technical-styles",
          layout: "two-column",
          theme: "light",
        },
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      // Compliance Report Template
      this.reportTemplates.set("compliance-assessment", {
        templateId: "compliance-assessment",
        name: "Compliance Assessment Report",
        description:
          "Detailed compliance assessment against security frameworks",
        reportType: "compliance",
        supportedFormats: ["html", "pdf", "csv", "json"],
        sections: [
          {
            id: "compliance-overview",
            name: "Compliance Overview",
            required: true,
            dataSource: "compliance-summary",
            template: "compliance-overview-template",
          },
          {
            id: "framework-assessment",
            name: "Framework Assessment",
            required: true,
            dataSource: "framework-data",
            template: "framework-template",
          },
          {
            id: "violations",
            name: "Compliance Violations",
            required: true,
            dataSource: "violations",
            template: "violations-template",
          },
          {
            id: "remediation-roadmap",
            name: "Remediation Roadmap",
            required: true,
            dataSource: "roadmap",
            template: "roadmap-template",
          },
        ],
        styles: {
          css: "compliance-styles",
          layout: "single-column",
          theme: "corporate",
        },
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      const duration = performance.now() - startTime;
      this.logger.info(
        `Reporting Engine: Default templates initialized in ${duration.toFixed(2)}ms`,
      );

      this.emit("templates_initialized", {
        templatesLoaded: this.reportTemplates.size,
        initializationTime: duration,
      });
    } catch (error) {
      this.logger.error(
        "Failed to initialize default report templates:",
        error,
      );
      throw new Error(
        `Reporting Engine initialization failed: ${(error as Error).message}`,
      );
    }
  }

  /**
   * Generate comprehensive vulnerability report
   */
  public async generateReport(
    config: ReportConfiguration,
    vulnerabilityData?: VulnerabilityAssessmentResult[],
    configurationData?: ConfigurationAnalysisResult[],
  ): Promise<GeneratedReport> {
    const reportId = config.reportId || this.generateReportId();
    const startTime = performance.now();
    const generatedAt = new Date();

    this.logger.info(`Generating report: ${reportId} (${config.reportType})`);
    this.emit("report_generation_started", { reportId, config });

    try {
      // Check for existing active report generation
      const existingReport = this.activeReports.get(reportId);
      if (existingReport) {
        this.logger.warn(`Report ${reportId} generation already in progress`);
        return await existingReport;
      }

      // Create report generation promise and track it
      const reportPromise = this.performReportGeneration(
        config,
        reportId,
        generatedAt,
        startTime,
        vulnerabilityData,
        configurationData,
      );
      this.activeReports.set(reportId, reportPromise);

      try {
        const result = await reportPromise;

        // Store completed report in history
        this.reportHistory.set(reportId, result);

        this.logger.info(`Report generated successfully: ${reportId}`);
        this.emit("report_generation_completed", result);

        return result;
      } finally {
        // Always clean up active report tracking
        this.activeReports.delete(reportId);
      }
    } catch (error) {
      const failedReport: GeneratedReport = {
        reportId,
        reportType: config.reportType,
        format: config.format,
        title: config.title || `${config.reportType} Report`,
        description: config.description,
        generatedAt,
        generatedBy: "VulnerabilityReportingEngine",
        generationDuration: performance.now() - startTime,
        dataSourceCount:
          (vulnerabilityData?.length || 0) + (configurationData?.length || 0),
        summary: {
          totalVulnerabilities: 0,
          totalConfigIssues: 0,
          criticalFindings: 0,
          highPriorityFindings: 0,
          overallRiskScore: 0,
          complianceScore: 0,
        },
        sections: [],
        exportedAt: generatedAt,
        version: "2.0.0",
      };

      this.logger.error(`Report generation failed: ${reportId}`, error);
      this.emit("report_generation_failed", {
        reportId,
        error: (error as Error).message,
      });

      return failedReport;
    }
  }

  /**
   * Core report generation implementation
   */
  private async performReportGeneration(
    config: ReportConfiguration,
    reportId: string,
    generatedAt: Date,
    startTime: number,
    vulnerabilityData?: VulnerabilityAssessmentResult[],
    configurationData?: ConfigurationAnalysisResult[],
  ): Promise<GeneratedReport> {
    // Aggregate and analyze data
    const aggregatedData = this.aggregateData(
      vulnerabilityData || [],
      configurationData || [],
    );

    // Apply filtering based on configuration
    const filteredData = this.applyFiltering(aggregatedData, config);

    // Calculate summary metrics
    const summary = this.calculateSummaryMetrics(filteredData);

    // Generate report sections
    const sections = await this.generateReportSections(filteredData, config);

    // Generate trends if requested
    const trends = config.includeTrendAnalysis
      ? await this.generateTrendAnalysis(filteredData, config)
      : undefined;

    // Export to specified format
    const exportResult = await this.exportReport(
      filteredData,
      config,
      sections,
      trends,
    );

    const generationDuration = performance.now() - startTime;

    const report: GeneratedReport = {
      reportId,
      reportType: config.reportType,
      format: config.format,
      title: config.title || this.generateReportTitle(config.reportType),
      description: config.description,
      generatedAt,
      generatedBy: "VulnerabilityReportingEngine",
      generationDuration,
      dataSourceCount:
        (vulnerabilityData?.length || 0) + (configurationData?.length || 0),
      summary,
      sections,
      trends,
      filePath: exportResult.filePath,
      fileSize: exportResult.fileSize,
      checksum: exportResult.checksum,
      exportedAt: new Date(),
      version: "2.0.0",
    };

    return report;
  }

  /**
   * Aggregate vulnerability and configuration data
   */
  private aggregateData(
    vulnerabilityData: VulnerabilityAssessmentResult[],
    configurationData: ConfigurationAnalysisResult[],
  ) {
    const allVulnerabilities: Vulnerability[] = [];
    const allConfigIssues: ConfigurationIssue[] = [];
    const assessmentSummaries: any[] = [];
    const analysisSummaries: any[] = [];

    // Aggregate vulnerability data
    vulnerabilityData.forEach((assessment) => {
      allVulnerabilities.push(...assessment.vulnerabilities);
      assessmentSummaries.push({
        id: assessment.scanId,
        type: "vulnerability_assessment",
        summary: assessment.summary,
        riskAssessment: assessment.riskAssessment,
        compliance: assessment.compliance,
        recommendations: assessment.recommendations,
        startedAt: assessment.startedAt,
        completedAt: assessment.completedAt,
      });
    });

    // Aggregate configuration data
    configurationData.forEach((analysis) => {
      allConfigIssues.push(...analysis.issues);
      analysisSummaries.push({
        id: analysis.analysisId,
        type: "configuration_analysis",
        summary: analysis.summary,
        compliance: analysis.compliance,
        recommendations: analysis.recommendations,
        startedAt: analysis.startedAt,
        completedAt: analysis.completedAt,
      });
    });

    return {
      vulnerabilities: allVulnerabilities,
      configurationIssues: allConfigIssues,
      assessmentSummaries,
      analysisSummaries,
      totalDataSources: vulnerabilityData.length + configurationData.length,
    };
  }

  /**
   * Apply filtering based on report configuration
   */
  private applyFiltering(aggregatedData: any, config: ReportConfiguration) {
    let filteredVulns = aggregatedData.vulnerabilities;
    let filteredConfigIssues = aggregatedData.configurationIssues;

    // Apply severity threshold
    if (config.severityThreshold) {
      const severityOrder = ["info", "low", "medium", "high", "critical"];
      const thresholdIndex = severityOrder.indexOf(config.severityThreshold);

      filteredVulns = filteredVulns.filter((vuln: Vulnerability) => {
        const vulnIndex = severityOrder.indexOf(vuln.severity);
        return vulnIndex >= thresholdIndex;
      });

      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) => {
          const issueIndex = severityOrder.indexOf(issue.severity);
          return issueIndex >= thresholdIndex;
        },
      );
    }

    // Apply category filter
    if (config.categoryFilter && config.categoryFilter.length > 0) {
      filteredVulns = filteredVulns.filter((vuln: Vulnerability) =>
        config.categoryFilter!.includes(vuln.category as any),
      );

      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) =>
          config.categoryFilter!.includes(issue.configType as any),
      );
    }

    // Apply tag filter
    if (config.tagFilter && config.tagFilter.length > 0) {
      filteredVulns = filteredVulns.filter((vuln: Vulnerability) =>
        vuln.tags.some((tag) => config.tagFilter!.includes(tag)),
      );

      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) =>
          issue.tags.some((tag) => config.tagFilter!.includes(tag)),
      );
    }

    // Apply date range filter
    if (config.dateRange) {
      filteredVulns = filteredVulns.filter((vuln: Vulnerability) => {
        const vulnDate = new Date(vuln.discoveredAt);
        return (
          vulnDate >= config.dateRange!.from && vulnDate <= config.dateRange!.to
        );
      });

      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) => {
          const issueDate = new Date(issue.discoveredAt);
          return (
            issueDate >= config.dateRange!.from &&
            issueDate <= config.dateRange!.to
          );
        },
      );
    }

    // Apply scope filtering
    if (config.scope === "critical_only") {
      filteredVulns = filteredVulns.filter(
        (vuln: Vulnerability) => vuln.severity === "critical",
      );
      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) => issue.severity === "critical",
      );
    } else if (config.scope === "high_priority") {
      filteredVulns = filteredVulns.filter(
        (vuln: Vulnerability) =>
          vuln.severity === "critical" || vuln.severity === "high",
      );
      filteredConfigIssues = filteredConfigIssues.filter(
        (issue: ConfigurationIssue) =>
          issue.severity === "critical" || issue.severity === "high",
      );
    }

    return {
      ...aggregatedData,
      vulnerabilities: filteredVulns,
      configurationIssues: filteredConfigIssues,
    };
  }

  /**
   * Calculate comprehensive summary metrics
   */
  private calculateSummaryMetrics(filteredData: any) {
    const vulnerabilities = filteredData.vulnerabilities;
    const configIssues = filteredData.configurationIssues;

    // Count findings by severity
    const criticalFindings =
      vulnerabilities.filter((v: Vulnerability) => v.severity === "critical")
        .length +
      configIssues.filter((i: ConfigurationIssue) => i.severity === "critical")
        .length;

    const highPriorityFindings =
      vulnerabilities.filter(
        (v: Vulnerability) =>
          v.severity === "critical" || v.severity === "high",
      ).length +
      configIssues.filter(
        (i: ConfigurationIssue) =>
          i.severity === "critical" || i.severity === "high",
      ).length;

    // Calculate overall risk score
    const totalRiskScore =
      vulnerabilities.reduce(
        (sum: number, vuln: Vulnerability) => sum + vuln.riskScore,
        0,
      ) +
      configIssues.reduce(
        (sum: number, issue: ConfigurationIssue) => sum + issue.riskScore,
        0,
      );
    const totalFindings = vulnerabilities.length + configIssues.length;
    const overallRiskScore =
      totalFindings > 0 ? totalRiskScore / totalFindings : 0;

    // Calculate compliance score (mock implementation)
    const complianceScore = Math.max(
      0,
      100 - criticalFindings * 25 - highPriorityFindings * 10,
    );

    return {
      totalVulnerabilities: vulnerabilities.length,
      totalConfigIssues: configIssues.length,
      criticalFindings,
      highPriorityFindings,
      overallRiskScore: Math.round(overallRiskScore * 100) / 100,
      complianceScore: Math.round(complianceScore * 100) / 100,
    };
  }

  /**
   * Generate report sections based on template and data
   */
  private async generateReportSections(
    filteredData: any,
    config: ReportConfiguration,
  ) {
    const sections = [];
    const template = this.reportTemplates.get(
      `${config.reportType}-${config.reportType === "executive" ? "summary" : config.reportType === "technical" ? "detailed" : "assessment"}`,
    );

    if (template) {
      for (const sectionTemplate of template.sections) {
        const sectionData = this.prepareSectionData(
          sectionTemplate.dataSource,
          filteredData,
        );

        sections.push({
          name: sectionTemplate.name,
          type: sectionTemplate.dataSource,
          itemCount: this.getSectionItemCount(
            sectionTemplate.dataSource,
            filteredData,
          ),
          riskLevel: this.determineSectionRiskLevel(
            sectionTemplate.dataSource,
            filteredData,
          ),
        });
      }
    } else {
      // Default sections for unknown templates
      if (filteredData.vulnerabilities.length > 0) {
        sections.push({
          name: "Vulnerabilities",
          type: "vulnerabilities",
          itemCount: filteredData.vulnerabilities.length,
          riskLevel: this.determineVulnerabilityRiskLevel(
            filteredData.vulnerabilities,
          ),
        });
      }

      if (filteredData.configurationIssues.length > 0) {
        sections.push({
          name: "Configuration Issues",
          type: "configuration",
          itemCount: filteredData.configurationIssues.length,
          riskLevel: this.determineConfigurationRiskLevel(
            filteredData.configurationIssues,
          ),
        });
      }
    }

    return sections;
  }

  /**
   * Generate trend analysis data
   */
  private async generateTrendAnalysis(
    filteredData: any,
    config: ReportConfiguration,
  ): Promise<TrendAnalysis["trends"]> {
    const period: TrendPeriod = "weekly"; // Default to weekly trends
    const dataPoints = [];

    // Generate mock trend data for the last 30 days
    const now = new Date();
    for (let i = 29; i >= 0; i--) {
      const date = new Date(now);
      date.setDate(date.getDate() - i);

      dataPoints.push({
        date,
        vulnerabilities:
          Math.floor(Math.random() * 50) +
          filteredData.vulnerabilities.length * (i / 30),
        riskScore: Math.random() * 10,
        complianceScore: Math.random() * 100,
      });
    }

    // Generate insights based on trend data
    const insights = [
      "Vulnerability count has decreased by 15% over the past month",
      "Critical vulnerabilities are trending downward",
      "Configuration security has improved significantly",
      "Compliance score shows steady improvement",
    ];

    return {
      period,
      dataPoints,
      insights,
    };
  }

  /**
   * Export report to specified format
   */
  private async exportReport(
    filteredData: any,
    config: ReportConfiguration,
    sections: any[],
    trends?: any,
  ): Promise<{ filePath?: string; fileSize?: number; checksum?: string }> {
    const exportResult: {
      filePath?: string;
      fileSize?: number;
      checksum?: string;
    } = {};

    if (config.outputPath) {
      let content: string;

      switch (config.format) {
        case "json":
          content = this.generateJSONReport(
            filteredData,
            config,
            sections,
            trends,
          );
          break;
        case "html":
          content = this.generateHTMLReport(
            filteredData,
            config,
            sections,
            trends,
          );
          break;
        case "markdown":
          content = this.generateMarkdownReport(
            filteredData,
            config,
            sections,
            trends,
          );
          break;
        case "csv":
          content = this.generateCSVReport(filteredData, config);
          break;
        case "sarif":
          content = this.generateSARIFReport(filteredData, config);
          break;
        default:
          content = this.generateJSONReport(
            filteredData,
            config,
            sections,
            trends,
          );
      }

      // Ensure output directory exists
      const outputDir = path.dirname(config.outputPath);
      await fs.mkdir(outputDir, { recursive: true });

      // Write report to file
      await fs.writeFile(config.outputPath, content, "utf-8");

      // Calculate file statistics
      const stats = await fs.stat(config.outputPath);
      const checksum = createHash("sha256").update(content).digest("hex");

      exportResult.filePath = config.outputPath;
      exportResult.fileSize = stats.size;
      exportResult.checksum = checksum;
    }

    return exportResult;
  }

  /**
