      markdown += `${config.description}\n\n`;
    }

    markdown += `**Generated:** ${new Date().toLocaleString()}\n`;
    markdown += `**Report Type:** ${config.reportType}\n`;
    if (config.companyName) {
      markdown += `**Company:** ${config.companyName}\n`;
    }
    markdown += `\n---\n\n`;

    // Executive Summary
    markdown += `## Executive Summary\n\n`;
    markdown += `| Metric | Value |\n`;
    markdown += `|--------|-------|\n`;
    markdown += `| Total Vulnerabilities | ${summary.totalVulnerabilities} |\n`;
    markdown += `| Configuration Issues | ${summary.totalConfigIssues} |\n`;
    markdown += `| Critical Findings | ${summary.criticalFindings} |\n`;
