      markdown += `## Vulnerabilities (${filteredData.vulnerabilities.length})\n\n`;
      markdown += `| Title | Severity | Category | Risk Score | Location |\n`;
      markdown += `|-------|----------|----------|------------|----------|\n`;

      filteredData.vulnerabilities
        .slice(0, 20)
        .forEach((vuln: Vulnerability) => {
          const location =
            vuln.location.file || vuln.location.endpoint || "N/A";
          markdown += `| ${vuln.title} | **${vuln.severity.toUpperCase()}** | ${vuln.category} | ${vuln.riskScore.toFixed(1)} | ${location} |\n`;
        });

      if (filteredData.vulnerabilities.length > 20) {
        markdown += `\n*... and ${filteredData.vulnerabilities.length - 20} more vulnerabilities*\n`;
      }
      markdown += `\n`;
    }

    // Configuration issues section
    if (
      config.scope !== "summary" &&
