  /**
   * Generate CSV format report
   */
  private generateCSVReport(
    filteredData: any,
    config: ReportConfiguration,
  ): string {
    let csv = "";

    // Vulnerabilities CSV
    if (filteredData.vulnerabilities.length > 0) {
      csv +=
        "Type,ID,Title,Severity,Category,Risk Score,Confidence,Location,CWE,CVE,Status,Discovered At\n";

      filteredData.vulnerabilities.forEach((vuln: Vulnerability) => {
        const location = vuln.location.file || vuln.location.endpoint || "N/A";
        csv += `Vulnerability,"${vuln.id}","${vuln.title}",${vuln.severity},${vuln.category},${vuln.riskScore},${vuln.confidence},"${location}",${vuln.cwe || ""},${vuln.cve || ""},${vuln.status},${vuln.discoveredAt.toISOString()}\n`;
      });
    }

    // Configuration issues CSV
    if (filteredData.configurationIssues.length > 0) {
      if (csv) csv += "\n";
      csv +=
        "Type,ID,Title,Severity,Config Type,Risk Score,Confidence,File,Line,Status,Discovered At\n";

      filteredData.configurationIssues.forEach((issue: ConfigurationIssue) => {
        csv += `Configuration Issue,"${issue.id}","${issue.title}",${issue.severity},${issue.configType},${issue.riskScore},${issue.confidence},"${issue.location.file}",${issue.location.line || ""},N/A,${issue.discoveredAt.toISOString()}\n`;
      });
    }

    return csv;
  }

  /**
   * Generate SARIF format report
   */
  private generateSARIFReport(
    filteredData: any,
    config: ReportConfiguration,
  ): string {
    const sarif = {
      version: "2.1.0",
      $schema: "https://json.schemastore.org/sarif-2.1.0.json",
      runs: [
        {
          tool: {
            driver: {
              name: "Bytebot Vulnerability Assessment Engine",
              version: "2.0.0",
              informationUri:
                "https://github.com/bytebot-org/vulnerability-scanner",
              rules: this.generateSARIFRules(filteredData),
            },
          },
          results: [
            ...filteredData.vulnerabilities.map((vuln: Vulnerability) => ({
              ruleId: vuln.cwe || vuln.category,
              level: this.mapSeverityToSARIFLevel(vuln.severity),
              message: { text: vuln.description },
              locations: [
                {
                  physicalLocation: {
                    artifactLocation: {
                      uri: vuln.location.file || "unknown",
                    },
                    region: {
                      startLine: vuln.location.line || 1,
                      startColumn: vuln.location.column || 1,
                    },
                  },
                },
              ],
              properties: {
                riskScore: vuln.riskScore,
                confidence: vuln.confidence,
                category: vuln.category,
                tags: vuln.tags,
              },
            })),
            ...filteredData.configurationIssues.map(
              (issue: ConfigurationIssue) => ({
                ruleId: issue.cwe || issue.category,
                level: this.mapSeverityToSARIFLevel(issue.severity),
                message: { text: issue.description },
                locations: [
                  {
                    physicalLocation: {
                      artifactLocation: {
                        uri: issue.location.file,
                      },
                      region: {
                        startLine: issue.location.line || 1,
                      },
                    },
                  },
                ],
                properties: {
                  riskScore: issue.riskScore,
                  confidence: issue.confidence,
                  configType: issue.configType,
                  tags: issue.tags,
                },
              }),
            ),
          ],
        },
      ],
    };

    return JSON.stringify(sarif, null, 2);
  }

