  private prepareSectionData(dataSource: string, filteredData: any): any {
    switch (dataSource) {
      case "vulnerabilities":
        return filteredData.vulnerabilities;
      case "configuration":
        return filteredData.configurationIssues;
      case "summary":
        return this.calculateSummaryMetrics(filteredData);
      default:
        return null;
    }
  }

  private getSectionItemCount(dataSource: string, filteredData: any): number {
    switch (dataSource) {
      case "vulnerabilities":
        return filteredData.vulnerabilities.length;
      case "configuration":
        return filteredData.configurationIssues.length;
      default:
        return 0;
    }
  }

  private determineSectionRiskLevel(
    dataSource: string,
    filteredData: any,
  ): "low" | "medium" | "high" | "critical" {
    let criticalCount = 0;
    let highCount = 0;

    if (dataSource === "vulnerabilities") {
      criticalCount = filteredData.vulnerabilities.filter(
        (v: Vulnerability) => v.severity === "critical",
      ).length;
      highCount = filteredData.vulnerabilities.filter(
        (v: Vulnerability) => v.severity === "high",
      ).length;
    } else if (dataSource === "configuration") {
      criticalCount = filteredData.configurationIssues.filter(
        (i: ConfigurationIssue) => i.severity === "critical",
      ).length;
      highCount = filteredData.configurationIssues.filter(
        (i: ConfigurationIssue) => i.severity === "high",
      ).length;
    }

    if (criticalCount > 0) return "critical";
    if (highCount > 5) return "high";
    if (highCount > 0) return "medium";
    return "low";
  }

  private determineVulnerabilityRiskLevel(
    vulnerabilities: Vulnerability[],
  ): "low" | "medium" | "high" | "critical" {
    const criticalCount = vulnerabilities.filter(
      (v) => v.severity === "critical",
    ).length;
    const highCount = vulnerabilities.filter(
      (v) => v.severity === "high",
    ).length;

    if (criticalCount > 0) return "critical";
    if (highCount > 5) return "high";
    if (highCount > 0) return "medium";
    return "low";
  }

  private determineConfigurationRiskLevel(
    issues: ConfigurationIssue[],
  ): "low" | "medium" | "high" | "critical" {
    const criticalCount = issues.filter(
      (i) => i.severity === "critical",
    ).length;
    const highCount = issues.filter((i) => i.severity === "high").length;

    if (criticalCount > 0) return "critical";
    if (highCount > 5) return "high";
    if (highCount > 0) return "medium";
    return "low";
  }

  private generateComplianceData(filteredData: any): any {
    // Mock compliance data generation
    return {
      OWASP: { score: 85, status: "partial" },
      NIST: { score: 78, status: "partial" },
      ISO27001: { score: 82, status: "partial" },
    };
  }

  private generateRecommendations(filteredData: any): any[] {
    const recommendations = [];

    // Critical vulnerability recommendations
    const criticalVulns = filteredData.vulnerabilities.filter(
      (v: Vulnerability) => v.severity === "critical",
    );
    if (criticalVulns.length > 0) {
      recommendations.push({
        title: "Address Critical Vulnerabilities",
        description: `${criticalVulns.length} critical vulnerabilities require immediate attention`,
        priority: 1,
      });
    }

    // Configuration issue recommendations
    const criticalConfigs = filteredData.configurationIssues.filter(
      (i: ConfigurationIssue) => i.severity === "critical",
    );
    if (criticalConfigs.length > 0) {
      recommendations.push({
        title: "Fix Critical Configuration Issues",
        description: `${criticalConfigs.length} critical configuration issues need immediate remediation`,
        priority: 2,
      });
    }

    // General security improvements
    recommendations.push({
      title: "Implement Continuous Security Monitoring",
      description:
        "Establish ongoing security monitoring and regular vulnerability assessments",
      priority: 3,
    });

    return recommendations;
  }

  private generateSARIFRules(filteredData: any): any[] {
    const rules = new Map();

    // Generate rules from vulnerabilities
    filteredData.vulnerabilities.forEach((vuln: Vulnerability) => {
      const ruleId = vuln.cwe || vuln.category;
      if (!rules.has(ruleId)) {
        rules.set(ruleId, {
          id: ruleId,
          name: vuln.title,
          shortDescription: { text: vuln.title },
          fullDescription: { text: vuln.description },
        });
      }
    });

    // Generate rules from configuration issues
    filteredData.configurationIssues.forEach((issue: ConfigurationIssue) => {
      const ruleId = issue.cwe || issue.category;
      if (!rules.has(ruleId)) {
        rules.set(ruleId, {
          id: ruleId,
          name: issue.title,
          shortDescription: { text: issue.title },
          fullDescription: { text: issue.description },
        });
      }
    });

    return Array.from(rules.values());
  }

  private mapSeverityToSARIFLevel(
    severity: VulnerabilitySeverity | MisconfigurationSeverity,
  ): string {
    switch (severity) {
      case "critical":
        return "error";
      case "high":
        return "error";
      case "medium":
        return "warning";
      case "low":
        return "note";
      case "info":
        return "note";
      default:
        return "warning";
    }
  }

  private generateReportId(): string {
    return `report_${Date.now()}_${randomBytes(6).toString("hex")}`;
  }

  /**
   * Get report history
   */
  public getReportHistory(limit?: number): GeneratedReport[] {
    const reports = Array.from(this.reportHistory.values()).sort(
      (a, b) => b.generatedAt.getTime() - a.generatedAt.getTime(),
    );

    return limit ? reports.slice(0, limit) : reports;
  }

  /**
   * Get report by ID
   */
  public getReportById(reportId: string): GeneratedReport | null {
    return this.reportHistory.get(reportId) || null;
  }

  /**
   * Get available templates
   */
  public getAvailableTemplates(): ReportTemplate[] {
    return Array.from(this.reportTemplates.values());
  }

  /**
   * Cancel active report generation
   */
  public async cancelReportGeneration(reportId: string): Promise<boolean> {
    const activeReport = this.activeReports.get(reportId);
    if (activeReport) {
      this.activeReports.delete(reportId);
      this.emit("report_generation_cancelled", { reportId });
      return true;
    }
    return false;
  }

  /**
   * Get reporting engine statistics
   */
  public getReportingStats(): {
    totalReports: number;
    activeReports: number;
    availableTemplates: number;
    supportedFormats: ReportFormat[];
  } {
    return {
      totalReports: this.reportHistory.size,
      activeReports: this.activeReports.size,
      availableTemplates: this.reportTemplates.size,
      supportedFormats: [
        "json",
        "xml",
        "html",
        "pdf",
        "csv",
        "sarif",
        "markdown",
        "xlsx",
      ],
    };
  }
}

