/**
 * Vulnerability Scanner Mock Implementation
 *
 * Mock implementation for security vulnerability scanning including:
 * - Code vulnerability scanning (SAST)
 * - Dependency vulnerability scanning (SCA)
 * - Infrastructure security scanning
 * - Container image scanning
 * - Web application security testing (DAST)
 * - OWASP Top 10 vulnerability detection
 *
 * @author Claude Code
 * @version 2.0.0
 */

import { MockConfig as _MockConfig } from "./mock-config";

export type VulnerabilitySeverity = "low" | "medium" | "high" | "critical";

export type VulnerabilityType =
  | "sql_injection"
  | "xss"
  | "csrf"
  | "insecure_deserialization"
  | "broken_authentication"
  | "sensitive_data_exposure"
  | "xml_external_entities"
  | "broken_access_control"
  | "security_misconfiguration"
  | "vulnerable_components"
  | "insufficient_logging"
  | "server_side_request_forgery"
  | "path_traversal"
  | "command_injection"
  | "buffer_overflow"
  | "weak_cryptography"
  | "hardcoded_secrets";

export type ScanType =
  | "code"
  | "dependencies"
  | "infrastructure"
  | "container"
  | "web_app"
  | "api";

export interface Vulnerability {
  id: string;
  type: VulnerabilityType;
  severity: VulnerabilitySeverity;
  title: string;
  description: string;
  location: {
    file?: string;
    line?: number;
    column?: number;
    function?: string;
    endpoint?: string;
    parameter?: string;
  };
  cwe?: string; // Common Weakness Enumeration
  cve?: string; // Common Vulnerabilities and Exposures
  cvss?: {
    version: string;
    score: number;
    vector: string;
  };
  impact: {
    confidentiality: "none" | "low" | "high";
    integrity: "none" | "low" | "high";
    availability: "none" | "low" | "high";
  };
  remediation: {
    effort: "low" | "medium" | "high";
    priority: number;
    suggestions: string[];
    references: string[];
  };
  confidence: number; // 0-100
  discovered_at: Date;
  status: "new" | "confirmed" | "false_positive" | "fixed" | "accepted_risk";
}

export interface ScanConfiguration {
  scanType: ScanType;
  target: string;
  includePatterns?: string[];
  excludePatterns?: string[];
  severityThreshold?: VulnerabilitySeverity;
  maxVulnerabilities?: number;
  timeout?: number;
  deepScan?: boolean;
  checkDependencies?: boolean;
  checkContainers?: boolean;
}

export interface ScanResult {
  scanId: string;
  scanType: ScanType;
  target: string;
  startedAt: Date;
  completedAt: Date;
  duration: number;
  status: "completed" | "failed" | "timeout" | "cancelled";
  vulnerabilities: Vulnerability[];
  summary: {
    total: number;
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
  metrics: {
    filesScanned: number;
    linesOfCode?: number;
    dependencies?: number;
    endpoints?: number;
    coverage?: number;
  };
  recommendations: string[];
  error?: string;
}

export interface VulnerabilityScannerMock {
  scan: jest.MockedFunction<
    (_config: ScanConfiguration) => Promise<ScanResult>
  >;
  scanCode: jest.MockedFunction<
    (
      _codebase: string,
      _options?: Partial<ScanConfiguration>,
    ) => Promise<ScanResult>
  >;
  scanDependencies: jest.MockedFunction<
    (
      _packageFile: string,
      _options?: Partial<ScanConfiguration>,
    ) => Promise<ScanResult>
  >;
  scanContainer: jest.MockedFunction<
    (
      _imageName: string,
      _options?: Partial<ScanConfiguration>,
    ) => Promise<ScanResult>
  >;
  scanWebApp: jest.MockedFunction<
    (_url: string, _options?: Partial<ScanConfiguration>) => Promise<ScanResult>
  >;
  scanApi: jest.MockedFunction<
    (
      _apiSpec: string,
      _baseUrl: string,
      _options?: Partial<ScanConfiguration>,
    ) => Promise<ScanResult>
  >;
  getScanHistory: jest.MockedFunction<
    (_limit?: number) => Promise<ScanResult[]>
  >;
  getScanById: jest.MockedFunction<
    (_scanId: string) => Promise<ScanResult | null>
  >;
  getVulnerabilityById: jest.MockedFunction<
    (_vulnerabilityId: string) => Promise<Vulnerability | null>
  >;
  updateVulnerabilityStatus: jest.MockedFunction<
    (
      _vulnerabilityId: string,
      _status: Vulnerability["status"],
      _reason?: string,
    ) => Promise<boolean>
  >;
  generateReport: jest.MockedFunction<
    (
      _scanId: string,
      _format: "json" | "xml" | "html" | "pdf" | "sarif",
    ) => Promise<string>
  >;
  getVulnerabilityStats: jest.MockedFunction<
    (_timeframe: "day" | "week" | "month" | "year") => Promise<{
      total: number;
      new: number;
      fixed: number;
      accepted: number;
      falsePositives: number;
      byType: Record<VulnerabilityType, number>;
      bySeverity: Record<VulnerabilitySeverity, number>;
      trend: { date: Date; count: number }[];
    }>
  >;
  exportFindings: jest.MockedFunction<
    (_scanId: string, _format: "csv" | "json" | "sarif") => Promise<string>
  >;
  validateConfiguration: jest.MockedFunction<
    (
      _config: ScanConfiguration,
    ) => Promise<{ valid: boolean; errors: string[] }>
  >;
  getScannerVersion: jest.MockedFunction<
    () => Promise<{ version: string; lastUpdated: Date; rulesCount: number }>
  >;
  updateSecurityRules: jest.MockedFunction<
    () => Promise<{
      success: boolean;
      rulesAdded: number;
      rulesUpdated: number;
    }>
  >;
}

// Mock storage for vulnerability scans
class MockVulnerabilityStore {
  private scans = new Map<string, ScanResult>();
  private vulnerabilities = new Map<string, Vulnerability>();

  addScan(scan: ScanResult): void {
    this.scans.set(scan.scanId, scan);
    scan.vulnerabilities.forEach((vuln) => {
      this.vulnerabilities.set(vuln.id, vuln);
    });
  }

  getScan(scanId: string): ScanResult | undefined {
    return this.scans.get(scanId);
  }

  getAllScans(limit?: number): ScanResult[] {
    const scans = Array.from(this.scans.values()).sort(
      (a, b) => b.startedAt.getTime() - a.startedAt.getTime(),
    );

    return limit ? scans.slice(0, limit) : scans;
  }

  getVulnerability(vulnerabilityId: string): Vulnerability | undefined {
    return this.vulnerabilities.get(vulnerabilityId);
  }

  updateVulnerabilityStatus(
    vulnerabilityId: string,
    status: Vulnerability["status"],
  ): boolean {
    const vulnerability = this.vulnerabilities.get(vulnerabilityId);
    if (vulnerability) {
      vulnerability.status = status;
      return true;
    }
    return false;
  }

  getVulnerabilityStats(timeframe: "day" | "week" | "month" | "year"): {
    total: number;
    new: number;
    fixed: number;
    accepted: number;
    falsePositives: number;
    byType: Record<VulnerabilityType, number>;
    bySeverity: Record<VulnerabilitySeverity, number>;
    trend: { date: Date; count: number }[];
  } {
    const cutoff = new Date();
    const cutoffDays = { day: 1, week: 7, month: 30, year: 365 }[timeframe];
    cutoff.setDate(cutoff.getDate() - cutoffDays);

    const relevantVulns = Array.from(this.vulnerabilities.values()).filter(
      (vuln) => vuln.discovered_at >= cutoff,
    );

    const byType: Record<VulnerabilityType, number> = {
      sql_injection: 0,
      xss: 0,
      csrf: 0,
      insecure_deserialization: 0,
      broken_authentication: 0,
      sensitive_data_exposure: 0,
      xml_external_entities: 0,
      broken_access_control: 0,
      security_misconfiguration: 0,
      vulnerable_components: 0,
      insufficient_logging: 0,
      server_side_request_forgery: 0,
      path_traversal: 0,
      command_injection: 0,
      buffer_overflow: 0,
      weak_cryptography: 0,
      hardcoded_secrets: 0,
    };

    const bySeverity: Record<VulnerabilitySeverity, number> = {
      low: 0,
      medium: 0,
      high: 0,
      critical: 0,
    };

    let newCount = 0;
    let fixedCount = 0;
    let acceptedCount = 0;
    let falsePositiveCount = 0;

    relevantVulns.forEach((vuln) => {
      byType[vuln.type]++;
      bySeverity[vuln.severity]++;

      switch (vuln.status) {
        case "new":
        case "confirmed":
          newCount++;
          break;
        case "fixed":
          fixedCount++;
          break;
        case "accepted_risk":
          acceptedCount++;
          break;
        case "false_positive":
          falsePositiveCount++;
          break;
      }
    });

    // Generate trend data (mock)
    const trend: { date: Date; count: number }[] = [];
    const daysToShow = Math.min(cutoffDays, 30);

    for (let i = daysToShow; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dailyCount = Math.floor(Math.random() * 10); // Mock data
      trend.push({ date, count: dailyCount });
    }

    return {
      total: relevantVulns.length,
      new: newCount,
      fixed: fixedCount,
      accepted: acceptedCount,
      falsePositives: falsePositiveCount,
      byType,
      bySeverity,
      trend,
    };
  }

  clear(): void {
    this.scans.clear();
    this.vulnerabilities.clear();
  }
}

// Singleton store instance
const mockVulnerabilityStore = new MockVulnerabilityStore();

/**
 * Creates a comprehensive vulnerability scanner mock
 */
export const createVulnerabilityScannerMock = (): VulnerabilityScannerMock => {
  const generateScanId = (): string => {
    return `scan_${Date.now()}_${Math.random().toString(36).substring(7)}`;
  };

  const generateVulnerabilityId = (): string => {
    return `vuln_${Date.now()}_${Math.random().toString(36).substring(7)}`;
  };

  const createMockVulnerabilities = (
    scanType: ScanType,
    target: string,
    count: number = 5,
  ): Vulnerability[] => {
    const vulnerabilityTypes: VulnerabilityType[] = [
      "sql_injection",
      "xss",
      "csrf",
      "broken_authentication",
      "sensitive_data_exposure",
      "security_misconfiguration",
      "vulnerable_components",
      "path_traversal",
      "weak_cryptography",
    ];

    const severities: VulnerabilitySeverity[] = [
      "low",
      "medium",
      "high",
      "critical",
    ];

    const vulnerabilities: Vulnerability[] = [];

    for (let i = 0; i < count; i++) {
      const type =
        vulnerabilityTypes[
          Math.floor(Math.random() * vulnerabilityTypes.length)
        ];
      const severity =
        severities[Math.floor(Math.random() * severities.length)];
      const confidence = 60 + Math.floor(Math.random() * 40); // 60-100

      const vulnerability: Vulnerability = {
        id: generateVulnerabilityId(),
        type,
        severity,
        title: `${type.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase())} Vulnerability`,
        description: `Detected ${type.replace(/_/g, " ")} vulnerability in ${target}`,
        location: {
          file:
            scanType === "code"
              ? `src/components/Component${i + 1}.ts`
              : undefined,
          line:
            scanType === "code"
              ? Math.floor(Math.random() * 500) + 1
              : undefined,
          endpoint:
            scanType === "web_app" || scanType === "api"
              ? `/api/endpoint${i + 1}`
              : undefined,
          parameter:
            scanType === "web_app" || scanType === "api"
              ? `param${i + 1}`
              : undefined,
        },
        cwe: `CWE-${Math.floor(Math.random() * 900) + 100}`,
        cve:
          Math.random() > 0.7
            ? `CVE-2024-${Math.floor(Math.random() * 9999)
                .toString()
                .padStart(4, "0")}`
            : undefined,
        cvss: {
          version: "3.1",
          score: parseFloat((Math.random() * 10).toFixed(1)),
          vector: "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
        },
        impact: {
          confidentiality:
            severity === "critical" || severity === "high" ? "high" : "low",
          integrity: severity === "critical" ? "high" : "low",
          availability: severity === "critical" ? "high" : "none",
        },
        remediation: {
          effort:
            severity === "critical"
              ? "high"
              : severity === "high"
                ? "medium"
                : "low",
          priority:
            severity === "critical"
              ? 1
              : severity === "high"
                ? 2
                : severity === "medium"
                  ? 3
                  : 4,
          suggestions: [
            `Implement proper ${type.replace(/_/g, " ")} protection`,
            "Update to latest secure version",
            "Apply security best practices",
          ],
          references: [
            `https://owasp.org/www-community/vulnerabilities/${type}`,
            `https://cwe.mitre.org/data/definitions/${Math.floor(Math.random() * 900) + 100}.html`,
          ],
        },
        confidence,
        discovered_at: new Date(),
        status: "new",
      };

      vulnerabilities.push(vulnerability);
    }

    return vulnerabilities;
  };

  const performMockScan = async (
    config: ScanConfiguration,
  ): Promise<ScanResult> => {
    const scanId = generateScanId();
    const startedAt = new Date();

    // Simulate scan duration
    await new Promise((resolve) => setTimeout(resolve, 100));

    const completedAt = new Date();
    const duration = completedAt.getTime() - startedAt.getTime();

    // Generate mock vulnerabilities based on scan type and configuration
    const maxVulns = config.maxVulnerabilities || 10;
    const vulnCount = Math.floor(Math.random() * maxVulns);
    const vulnerabilities = createMockVulnerabilities(
      config.scanType,
      config.target,
      vulnCount,
    );

    // Filter by severity threshold if specified
    const filteredVulns = config.severityThreshold
      ? vulnerabilities.filter((v) => {
          const severityOrder = ["low", "medium", "high", "critical"];
          const thresholdIndex = severityOrder.indexOf(
            config.severityThreshold!,
          );
          const vulnIndex = severityOrder.indexOf(v.severity);
          return vulnIndex >= thresholdIndex;
        })
      : vulnerabilities;

    // Calculate summary
    const summary = {
      total: filteredVulns.length,
      critical: filteredVulns.filter((v) => v.severity === "critical").length,
      high: filteredVulns.filter((v) => v.severity === "high").length,
      medium: filteredVulns.filter((v) => v.severity === "medium").length,
      low: filteredVulns.filter((v) => v.severity === "low").length,
    };

    // Generate mock metrics
    const metrics = {
      filesScanned:
        config.scanType === "code" ? Math.floor(Math.random() * 500) + 50 : 0,
      linesOfCode:
        config.scanType === "code"
