// Default mock instance
export const vulnerabilityScannerMock = createVulnerabilityScannerMock();

// Mock vulnerability scanner factory with configurable behavior
export const createMockVulnerabilityScanner = (
  options: {
    alwaysFindVulnerabilities?: boolean;
    neverFindVulnerabilities?: boolean;
    simulateTimeout?: boolean;
    simulateLatency?: number;
    failureRate?: number;
    maxVulnerabilities?: number;
  } = {},
) => {
  const {
    alwaysFindVulnerabilities = false,
    neverFindVulnerabilities = false,
    simulateTimeout = false,
    simulateLatency = 0,
    failureRate = 0,
    maxVulnerabilities: _maxVulnerabilities = 50,
  } = options;

  const mock = createVulnerabilityScannerMock();

  // Override scan behavior
  if (neverFindVulnerabilities) {
    const originalScan = mock.scan;
    mock.scan = jest.fn(async (config) => {
      const result = await originalScan(config);
      return {
        ...result,
        vulnerabilities: [],
        summary: { total: 0, critical: 0, high: 0, medium: 0, low: 0 },
      };
    });
  }

  if (alwaysFindVulnerabilities) {
    const originalScan = mock.scan;
    mock.scan = jest.fn(async (config) => {
      const result = await originalScan(config);
      if (result.vulnerabilities.length === 0) {
        const mockVulns = createVulnerabilityScannerMock()[
          "createMockVulnerabilities"
        ](config.scanType, config.target, 5);
        const summary = {
          total: mockVulns.length,
          critical: mockVulns.filter((v) => v.severity === "critical").length,
          high: mockVulns.filter((v) => v.severity === "high").length,
          medium: mockVulns.filter((v) => v.severity === "medium").length,
          low: mockVulns.filter((v) => v.severity === "low").length,
        };

        return {
          ...result,
          vulnerabilities: mockVulns,
          summary,
        };
      }
      return result;
    });
  }

  if (simulateTimeout) {
    const originalScan = mock.scan;
    mock.scan = jest.fn(async (config) => {
      const result = await originalScan(config);
      return {
        ...result,
        status: "timeout" as const,
        error: "Scan timed out after configured timeout period",
      };
    });
  }

  // Add latency simulation
  if (simulateLatency > 0) {
    const originalMethods = {
      scan: mock.scan,
      scanCode: mock.scanCode,
      scanDependencies: mock.scanDependencies,
    };

    Object.entries(originalMethods).forEach(([methodName, originalMethod]) => {
      (mock as any)[methodName] = jest.fn(async (...args: any[]) => {
        await new Promise((resolve) => setTimeout(resolve, simulateLatency));
        return (originalMethod as any)(...args);
      });
    });
  }

  // Add random failure simulation
  if (failureRate > 0) {
    const scanMethods = [
      "scan",
      "scanCode",
      "scanDependencies",
      "scanContainer",
      "scanWebApp",
      "scanApi",
    ];

    scanMethods.forEach((methodName) => {
      const originalMethod = (mock as any)[methodName];
      (mock as any)[methodName] = jest.fn(async (...args: any[]) => {
        if (Math.random() < failureRate) {
          throw new Error("Vulnerability scanner temporarily unavailable");
        }
        return originalMethod(...args);
      });
    });
  }

  return mock;
};

