    console.log("🌐 Starting Network Security Scanner");
    console.log(`Targets: ${config.targetHosts?.join(", ")}`);
    console.log(
      `Port Ranges: ${config.portRanges?.map((r) => `${r.start}-${r.end}`).join(", ")}`,
    );
    console.log("─".repeat(80));

