  longTerm: RemediationTask[];
  estimatedCost: string;
  estimatedEffort: string;
}

interface RemediationTask {
  id: string;
  priority: "critical" | "high" | "medium" | "low";
  title: string;
  description: string;
  category: string;
  effort: "low" | "medium" | "high";
