// Export test utilities for use in test files
export const TestUtils = {
  performanceMonitor,
  TestDataFactory,

  /**
   * Measures execution time of a function
   */
  measureExecutionTime: <T>(fn: () => T): { result: T; duration: number } => {
    const startTime = performance.now();
    const result = fn();
    const endTime = performance.now();
    const duration = endTime - startTime;

    return { result, duration };
  },

  /**
   * Tests function with multiple inputs
   */
  testWithInputs: <T>(
    fn: (input: any) => T,
    inputs: any[],
  ): Array<{ input: any; result: T; error?: Error }> => {
    return inputs.map((input) => {
      try {
        const result = fn(input);
        return { input, result };
      } catch (error) {
        return { input, result: null as any, error: error as Error };
      }
    });
  },

  /**
   * Creates a mock implementation
   */
  createMock: <T extends Record<string, any>>(obj: T): jest.Mocked<T> => {
    const mock: any = {};

    for (const key in obj) {
      if (typeof obj[key] === "function") {
        mock[key] = jest.fn();
      } else if (typeof obj[key] === "object" && obj[key] !== null) {
        mock[key] = TestUtils.createMock(obj[key]);
      } else {
        mock[key] = obj[key];
      }
    }

    return mock;
  },

  /**
   * Validates security of input/output pairs
   */
  validateSecurityTransformation: (input: string, output: string): boolean => {
    // Check if dangerous patterns were removed
    const dangerousPatterns = [
      /<script[^>]*>.*?<\/script>/gi,
      /javascript:/gi,
      /on\w+\s*=/gi,
    ];

    const inputHasDangerous = dangerousPatterns.some((pattern) =>
      pattern.test(input),
    );
    const outputHasDangerous = dangerousPatterns.some((pattern) =>
      pattern.test(output),
    );

    return !inputHasDangerous || (inputHasDangerous && !outputHasDangerous);
  },

  /**
   * Generates random test data
   */
  generateRandomString: (length: number = 10): string => {
    const chars =
      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let result = "";
    for (let i = 0; i < length; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
  },
};

